ext('c10_eng_ch10',[
C("🌿","ओड क्या होता है",["किसी विषय की प्रशंसा में गंभीर गीत","भावनात्मक और ऊँचे स्वर की कविता","यहाँ विषय: एकांत","प्रशंसा सादे जीवन की"],"कविता का शीर्षक है ओड ऑन सॉलिट्यूड। ओड का मतलब है किसी व्यक्ति, वस्तु या भाव की प्रशंसा में लिखा गया गंभीर और भावपूर्ण गीत। यहाँ कवि एकांत की प्रशंसा कर रहे हैं, यानी ऐसे जीवन की जिसमें शांति है और भीड़ तथा दिखावा नहीं। ध्यान दीजिए, सॉलिट्यूड का मतलब एकांत है, जो मन को शांति देता है, जबकि लोनलीनेस यानी अकेलापन दुख देता है। कवि दूसरे प्रकार के जीवन की नहीं, बल्कि पहले प्रकार के शांत, संतुष्ट और आत्मनिर्भर जीवन की बात करते हैं।"),
C("✍️","अलेक्ज़ेंडर पोप",["18वीं सदी के इंग्लैंड के कवि","बचपन से बीमार, कद छोटा","बारह साल की उम्र में यह कविता लिखी","तुकबंदी और संतुलन के माहिर"],"कवि अलेक्ज़ेंडर पोप अठारहवीं सदी के इंग्लैंड के प्रमुख कवियों में गिने जाते हैं। बचपन से वे बीमार रहते थे और उनका कद भी छोटा रह गया था, फिर भी उन्होंने अपनी कमज़ोरियों को अपनी रचनात्मकता के आड़े नहीं आने दिया। कहा जाता है कि यह कविता उन्होंने बहुत कम उम्र में लिखी थी। उनकी कविताओं में संतुलित भाषा और सुंदर तुकबंदी मिलती है। उनकी जीवन-कथा हमें सिखाती है कि शारीरिक कठिनाई भी बड़ी सफलता में बाधा नहीं बनती, अगर इरादा मज़बूत हो।"),
C("🌾","पहला छंद: सीमित इच्छाएँ",["थोड़े से खेत में संतोष","जन्मभूमि की हवा में सुख","बड़ी इच्छाओं से दूरी","आत्म-संतोष का जीवन"],"पहले छंद का भाव समझिए। कवि कहते हैं कि वह आदमी सुखी है जिसकी इच्छाएँ और चिंताएँ पूर्वजों से मिले कुछ एकड़ खेत तक ही सीमित हैं। जो अपनी जन्मभूमि की हवा में साँस लेकर संतुष्ट है। आज हम हर समय और ज़्यादा पाने के लिए दौड़ते रहते हैं, और उसी में बेचैनी बढ़ती है। कवि बताते हैं कि जब इच्छाएँ सीमित होती हैं, तो मन अपने आप शांत रहता है। जैसे हमारे दादाजी, जो अपने गाँव, अपने खेत और अपने घर में पूरी तरह ख़ुश रहते हैं।"),
C("🐄","दूसरा छंद: आत्मनिर्भरता",["गाएँ दूध देती हैं","खेत अनाज देते हैं","भेड़ें ऊन और कपड़े","पेड़ छाया और जलावन"],"दूसरे छंद में कवि उस आदमी की ज़रूरतों की सूची देते हैं। उसकी गायें दूध देती हैं, खेत अनाज देते हैं, भेड़ें ऊन देती हैं जिससे कपड़े बनते हैं और पेड़ गर्मी में छाया और सर्दी में जलाने की लकड़ी देते हैं। यानी उसकी लगभग सारी ज़रूरतें अपनी ही ज़मीन से पूरी हो जाती हैं। इसे आत्मनिर्भरता कहते हैं। आज की भाषा में आत्मनिर्भर भारत का भी यही विचार है, कि हम अपनी ज़रूरत की चीज़ें अपने ही संसाधनों से बनाने में सक्षम बनें।"),
C("⏳","तीसरा छंद: बिना हड़बड़ी का समय",["घंटे, दिन, साल शांति से बीतें","स्वस्थ शरीर, शांत मन","दिन में सुकून","तनाव और दौड़ से दूर"],"तीसरे छंद में समय की बात है। कवि कहते हैं कि वह आदमी धन्य है जो बिना चिंता के अपने घंटों, दिनों और सालों को आराम से बीतते देखता है। उसका शरीर स्वस्थ होता है और मन शांत। यहाँ तनाव और भागदौड़ नहीं है। यह उसी विचार से जुड़ा है जो हमने पिछले निबंध, द पेस फ़ॉर लिविंग, में देखा था। जब हम हर पल घड़ी के पीछे भागते हैं, तब जीवन का रस खो देते हैं। कवि चाहते हैं कि हम अपनी रफ़्तार थोड़ी धीमी करें।"),
C("🌙","चौथा छंद: संतुलित जीवन",["रात को गहरी नींद","पढ़ाई और आराम का मेल","मीठा मनोरंजन","भोलापन और चिंतन"],"चौथे छंद में संतुलित जीवन का चित्र है। रात को गहरी नींद आती है, दिन में पढ़ाई और आराम दोनों का मेल रहता है, मनोरंजन भी मीठा और सरल है, और मन में भोलापन तथा चिंतन का समय है। यहाँ कवि सिर्फ़ आराम की बात नहीं करते, पढ़ाई को भी जगह देते हैं। इसका अर्थ है कि संतोष का मतलब आलस नहीं है। हम विद्यार्थी भी इसी संतुलन से सीख सकते हैं, पढ़ने के समय पूरा ध्यान और आराम के समय पूरा आराम।"),
C("🪦","पाँचवाँ छंद: गुमनामी की इच्छा",["बिना प्रसिद्धि के जीना","चुपचाप चले जाना","क़ब्र पर पत्थर भी नहीं","नाम की चाह नहीं"],"अंतिम छंद सबसे गहरा है। कवि अपनी इच्छा बताते हैं कि मुझे बिना किसी की नज़र में आए, बिना शोहरत के जीने दो और बिना किसी के शोक के चुपचाप दुनिया से चले जाने दो, और मेरी क़ब्र पर कोई पत्थर भी न हो जो बताए कि मैं कहाँ सोया हूँ। यहाँ कवि को नाम, शोहरत या बड़े स्मारक की चाह नहीं है। यह हमें सोचने पर मजबूर करता है कि कहीं हम दूसरों की नज़रों में छाए रहने की दौड़ में अपना असली सुख तो नहीं खो रहे।"),
C("📱","आज की प्रसिद्धि की दौड़",["सोशल मीडिया के फ़ॉलोअर","दिखावे का दबाव","तुलना से तनाव","असली सुख शांति में"],"आज के समय में यह कविता और भी प्रासंगिक है। हर कोई सोशल मीडिया पर लाइक और फ़ॉलोअर के पीछे भाग रहा है। इसके चक्कर में दिखावे का दबाव बढ़ता है और दूसरों से तुलना होती रहती है, जिससे तनाव पैदा होता है। कवि बताते हैं कि प्रसिद्धि के साथ चिंता भी आती है। असली सुख शांति और संतोष में है, लोगों की तारीफ़ में नहीं। इसलिए सोशल मीडिया का प्रयोग सीमा में कीजिए, और अपने असली रिश्तों और पढ़ाई को ज़्यादा समय दीजिए।"),
C("🎼","तुक और छंद की बनावट",["हर छंद में चार पंक्तियाँ","तुक योजना ए बी ए बी","चौथी पंक्ति छोटी","ठहराव और शांति का एहसास"],"कविता की बनावट पर ध्यान दीजिए। हर छंद में चार पंक्तियाँ हैं और तुक योजना ए बी ए बी है, यानी पहली और तीसरी पंक्ति की तुक मिलती है और दूसरी और चौथी की। जैसे केयर के साथ एयर, और बाउंड के साथ ग्राउंड। हर छंद की चौथी पंक्ति छोटी है, जो एक शांत ठहराव का एहसास देती है, बिल्कुल कविता के शांत भाव की तरह। परीक्षा में तुक योजना पूछी जाए, तो ए बी ए बी लिखिए और एक उदाहरण दीजिए।"),
C("📝","शब्दार्थ दोहराइए",["पैटर्नल एकर्स यानी पुश्तैनी खेत","कंटेंट यानी संतुष्ट","हर्ड्स और फ़्लॉक्स","रिक्रिएशन यानी मनोरंजन"],"आइए नए शब्द दोहराएँ। पैटर्नल एकर्स यानी पुश्तैनी खेत, कंटेंट यानी संतुष्ट, हर्ड्स यानी पशुओं का झुंड, फ़्लॉक्स यानी भेड़ों का झुंड और रिक्रिएशन यानी मनोरंजन। साथ में अटायर, यील्ड और अनलैमेंटेड भी याद कीजिए। अब हर शब्द से एक वाक्य बनाइए। जैसे हीज़ कंटेंट विद हिज़ सिंपल लाइफ़, यानी वह अपने सादे जीवन से संतुष्ट है। और द फ़ील्ड्स यील्ड गुड क्रॉप्स, यानी खेत अच्छी फ़सल देते हैं। इन्हें अपनी कॉपी में लिखिए।"),
C("🧩","व्याकरण: रिलेटिव क्लॉज़",["हू, व्हिच, वॉट से जुड़े वाक्य","ब्लेस्ड इज़ ही हू...","एक वाक्य में दो जानकारी","संयुक्त वाक्य सरल बनाना"],"इस कविता में बहुत से वाक्य रिलेटिव क्लॉज़ वाले हैं, जिनमें हू, व्हिच या दैट से दूसरी जानकारी जुड़ती है। जैसे ब्लेस्ड इज़ ही हू इज़ कंटेंट, यानी धन्य है वह जो संतुष्ट है। या द फ़ार्मर हू वर्क्स हार्ड इज़ हैप्पी, यानी जो किसान मेहनत करता है वह ख़ुश है। हू इंसान के लिए, व्हिच चीज़ों के लिए और दैट दोनों के लिए आता है। अपने आसपास के लोगों पर चार वाक्य बनाइए जिनमें हू का प्रयोग हो।"),
C("🏞️","बिहार की जीवनशैली से मेल",["गाय, खेत, आम और नीम की छाँव","जाड़े में अलाव","कबीर का दोहा: साईं इतना दीजिए","संतोषी सदा सुखी"],"यह कविता हमारे बिहार के गाँव जैसी लगती है। गाय का दूध, खेत का अनाज, आम और नीम की छाँव और जाड़ों में पुआल या लकड़ी का अलाव। संत कबीर ने भी इसी भाव को अपने दोहे में कहा है कि हे ईश्वर, मुझे इतना दीजिए जिसमें मेरा परिवार पल जाए और आने वाला मेहमान भी भूखा न लौटे। कहावत भी है कि संतोषी सदा सुखी। पर याद रखिए, संतोष का मतलब मेहनत छोड़ना नहीं है। कवि भी पढ़ाई और चिंतन की बात करते हैं।"),
C("📌","कविता का सार",["सीमित इच्छाओं वाला सुखी","आत्मनिर्भर और शांत जीवन","संतुलित दिनचर्या","संदेश: प्रसिद्धि से बढ़कर संतोष"],"अब कविता का सार दोहरा लें। अलेक्ज़ेंडर पोप की इस कविता में सुखी आदमी वह है जिसकी इच्छाएँ सीमित हैं, जो अपनी ज़मीन से अपनी ज़रूरतें पूरी करता है और जिसका मन शांत है। उसका दिन संतुलित है और रात को गहरी नींद आती है। अंत में कवि गुमनामी में सरल जीवन और शांत विदाई की इच्छा जताते हैं। संदेश है कि सच्चा सुख धन और प्रसिद्धि में नहीं, बल्कि सादे और संतुष्ट जीवन में है। इसे पाँच वाक्यों में अपने शब्दों में लिखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं","सुखी आदमी कौन है","कविता की तुक योजना","कवि अंत में क्या चाहते हैं"],"परीक्षा के प्रश्न देखिए। पहला, कवि कौन हैं? उत्तर, अलेक्ज़ेंडर पोप, इंग्लैंड के। दूसरा, कवि के अनुसार सुखी आदमी कौन है? उत्तर, जो अपनी सीमित ज़मीन से संतुष्ट और आत्मनिर्भर है। तीसरा, तुक योजना क्या है? उत्तर, ए बी ए बी। चौथा, कवि अंत में क्या चाहते हैं? उत्तर, बिना प्रसिद्धि के जीना और शांति से चले जाना। उत्तर पूरे वाक्य में लिखिए।"),
Q("आपके अनुसार सच्चा सुख किसमें है, धन में या संतोष में?","संतोष में, क्योंकि धन से सुविधा मिलती है पर मन की शांति संतोष से ही आती है।","एक सोचने वाला प्रश्न। आपके अनुसार सच्चा सुख किसमें है, धन में या संतोष में? सोचिए। ... संतोष में, क्योंकि धन से सुविधा मिलती है, पर मन की शांति संतोष से ही आती है। अपना उत्तर कारण सहित लिखिए।"),
],7)
